using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_ReturnsCorrectPage()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(items, 1, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
        }

        [Fact]
        public void Create_SecondPage_ReturnsCorrectItems()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(items, 2, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(11, result[0]);
            Assert.Equal(2, result.PageIndex);
        }

        [Fact]
        public void Create_LastPage_ReturnsRemainingItems()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(items, 3, 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(21, result[0]);
        }

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            var items = Enumerable.Range(1, 20).AsQueryable();

            var result = PaginatedList<int>.Create(items, 1, 10);

            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            var items = Enumerable.Range(1, 20).AsQueryable();

            var result = PaginatedList<int>.Create(items, 2, 10);

            Assert.True(result.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse()
        {
            var items = Enumerable.Range(1, 20).AsQueryable();

            var result = PaginatedList<int>.Create(items, 2, 10);

            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void HasNextPage_FirstPage_ReturnsTrue()
        {
            var items = Enumerable.Range(1, 20).AsQueryable();

            var result = PaginatedList<int>.Create(items, 1, 10);

            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void TotalPages_CalculatesCorrectly()
        {
            var items = Enumerable.Range(1, 15).AsQueryable();

            var result = PaginatedList<int>.Create(items, 1, 10);

            Assert.Equal(2, result.TotalPages);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            var items = Enumerable.Empty<int>().AsQueryable();

            var result = PaginatedList<int>.Create(items, 1, 10);

            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
        }

        [Fact]
        public void Create_SingleItem_OnePageNoNext()
        {
            var items = new[] { 42 }.AsQueryable();

            var result = PaginatedList<int>.Create(items, 1, 10);

            Assert.Single(result);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasNextPage);
            Assert.False(result.HasPreviousPage);
        }
    }
}

using ContosoUniversity.Models;
using System.ComponentModel.DataAnnotations;
using Xunit;

namespace ContosoUniversity.Tests.Models
{
    public class ModelValidationTests
    {
        private IList<ValidationResult> ValidateModel(object model)
        {
            var results = new List<ValidationResult>();
            var context = new ValidationContext(model, null, null);
            Validator.TryValidateObject(model, context, results, true);
            return results;
        }

        [Fact]
        public void Student_ValidModel_NoErrors()
        {
            var student = new Student
            {
                LastName = "Doe",
                FirstMidName = "John",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var results = ValidateModel(student);

            Assert.Empty(results);
        }

        [Fact]
        public void Student_MissingLastName_HasError()
        {
            var student = new Student
            {
                FirstMidName = "John",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var results = ValidateModel(student);

            Assert.Contains(results, r => r.MemberNames.Contains("LastName"));
        }

        [Fact]
        public void Student_MissingFirstName_HasError()
        {
            var student = new Student
            {
                LastName = "Doe",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var results = ValidateModel(student);

            Assert.Contains(results, r => r.MemberNames.Contains("FirstMidName"));
        }

        [Fact]
        public void Student_LastNameTooLong_HasError()
        {
            var student = new Student
            {
                LastName = new string('A', 51),
                FirstMidName = "John",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var results = ValidateModel(student);

            Assert.Contains(results, r => r.MemberNames.Contains("LastName"));
        }

        [Fact]
        public void Course_ValidModel_NoErrors()
        {
            var course = new Course
            {
                CourseID = 1001,
                Title = "Introduction to CS",
                Credits = 3,
                DepartmentID = 1
            };

            var results = ValidateModel(course);

            Assert.Empty(results);
        }

        [Fact]
        public void Course_TitleTooShort_HasError()
        {
            var course = new Course
            {
                CourseID = 1001,
                Title = "AB",
                Credits = 3,
                DepartmentID = 1
            };

            var results = ValidateModel(course);

            Assert.Contains(results, r => r.MemberNames.Contains("Title"));
        }

        [Fact]
        public void Course_CreditsOutOfRange_HasError()
        {
            var course = new Course
            {
                CourseID = 1001,
                Title = "Test Course",
                Credits = 6,
                DepartmentID = 1
            };

            var results = ValidateModel(course);

            Assert.Contains(results, r => r.MemberNames.Contains("Credits"));
        }

        [Fact]
        public void Department_ValidModel_NoErrors()
        {
            var dept = new Department
            {
                Name = "Engineering",
                Budget = 100000,
                StartDate = new DateTime(2020, 1, 1)
            };

            var results = ValidateModel(dept);

            Assert.Empty(results);
        }

        [Fact]
        public void Department_NameTooShort_HasError()
        {
            var dept = new Department
            {
                Name = "AB",
                Budget = 100000,
                StartDate = new DateTime(2020, 1, 1)
            };

            var results = ValidateModel(dept);

            Assert.Contains(results, r => r.MemberNames.Contains("Name"));
        }

        [Fact]
        public void Instructor_ValidModel_NoErrors()
        {
            var instructor = new Instructor
            {
                LastName = "Smith",
                FirstMidName = "John",
                HireDate = new DateTime(2020, 1, 1)
            };

            var results = ValidateModel(instructor);

            Assert.Empty(results);
        }

        [Fact]
        public void Instructor_MissingLastName_HasError()
        {
            var instructor = new Instructor
            {
                FirstMidName = "John",
                HireDate = new DateTime(2020, 1, 1)
            };

            var results = ValidateModel(instructor);

            Assert.Contains(results, r => r.MemberNames.Contains("LastName"));
        }

        [Fact]
        public void Notification_ValidModel_NoErrors()
        {
            var notification = new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test message",
                CreatedAt = DateTime.Now
            };

            var results = ValidateModel(notification);

            Assert.Empty(results);
        }

        [Fact]
        public void Notification_MissingEntityType_HasError()
        {
            var notification = new Notification
            {
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test message",
                CreatedAt = DateTime.Now
            };

            var results = ValidateModel(notification);

            Assert.Contains(results, r => r.MemberNames.Contains("EntityType"));
        }

        [Fact]
        public void OfficeAssignment_LocationTooLong_HasError()
        {
            var office = new OfficeAssignment
            {
                InstructorID = 1,
                Location = new string('A', 51)
            };

            var results = ValidateModel(office);

            Assert.Contains(results, r => r.MemberNames.Contains("Location"));
        }

        [Fact]
        public void Person_FullName_FormatIsCorrect()
        {
            var student = new Student
            {
                LastName = "Doe",
                FirstMidName = "Jane",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };

            Assert.Equal("Doe, Jane", student.FullName);
        }
    }
}

