            Assert.Equal("Admin", retrieved.Administrator.LastName);
        }

        [Fact]
        public void CanAddCourseWithDepartment()
        {
            var dept = new Department
            {
                Name = "CS Dept",
                Budget = 100000,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 5001,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var retrieved = _context.Courses.Include(c => c.Department)
                .First(c => c.CourseID == 5001);
            Assert.Equal("CS Dept", retrieved.Department.Name);
        }

        [Fact]
        public void CanCreateEnrollment()
        {
            var student = new Student
            {
                LastName = "EnrollStudent",
                FirstMidName = "Test",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };
            _context.Students.Add(student);

            var dept = new Department
            {
                Name = "Enroll Dept",
                Budget = 50000,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 6001,
                Title = "Enrolled Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var enrollment = new Enrollment
            {
                StudentID = student.ID,
                CourseID = course.CourseID,
                Grade = Grade.A
            };
            _context.Enrollments.Add(enrollment);
            _context.SaveChanges();

            var retrieved = _context.Enrollments
                .Include(e => e.Student)
                .Include(e => e.Course)
                .First(e => e.EnrollmentID == enrollment.EnrollmentID);

            Assert.Equal("EnrollStudent", retrieved.Student.LastName);
            Assert.Equal("Enrolled Course", retrieved.Course.Title);
            Assert.Equal(Grade.A, retrieved.Grade);
        }

        [Fact]
        public void CanCreateCourseAssignment()
        {
            var instructor = new Instructor
            {
                LastName = "AssignInstructor",
                FirstMidName = "Test",
                HireDate = new DateTime(2020, 1, 1)
            };
            _context.Instructors.Add(instructor);

            var dept = new Department
            {
                Name = "Assign Dept",
                Budget = 50000,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 7001,
                Title = "Assign Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            var assignment = new CourseAssignment
            {
                InstructorID = instructor.ID,
                CourseID = course.CourseID
            };
            _context.CourseAssignments.Add(assignment);
            _context.SaveChanges();

            var retrieved = _context.CourseAssignments
                .Include(ca => ca.Instructor)
                .Include(ca => ca.Course)
                .First(ca => ca.InstructorID == instructor.ID && ca.CourseID == course.CourseID);

            Assert.Equal("AssignInstructor", retrieved.Instructor.LastName);
            Assert.Equal("Assign Course", retrieved.Course.Title);
        }

        [Fact]
        public void CanCreateOfficeAssignment()
        {
            var instructor = new Instructor
            {
                LastName = "OfficeInstructor",
                FirstMidName = "Test",
                HireDate = new DateTime(2020, 1, 1)
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var office = new OfficeAssignment
            {
                InstructorID = instructor.ID,
                Location = "Building A Room 101"
            };
            _context.OfficeAssignments.Add(office);
            _context.SaveChanges();

            var retrieved = _context.OfficeAssignments
                .Include(o => o.Instructor)
                .First(o => o.InstructorID == instructor.ID);

            Assert.Equal("Building A Room 101", retrieved.Location);
            Assert.Equal("OfficeInstructor", retrieved.Instructor.LastName);
        }

        [Fact]
        public void CanStoreNotification()
        {
            var notification = new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test notification",
                CreatedAt = DateTime.Now,
                CreatedBy = "TestUser",
                IsRead = false
            };
            _context.Notifications.Add(notification);
            _context.SaveChanges();

            var retrieved = _context.Notifications.First(n => n.EntityId == "1");
            Assert.Equal("Test notification", retrieved.Message);
            Assert.False(retrieved.IsRead);
        }

        [Fact]
        public void PersonFullName_ReturnsConcatenatedName()
        {
            var student = new Student
            {
                LastName = "Doe",
                FirstMidName = "Jane",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };

            Assert.Equal("Doe, Jane", student.FullName);
        }

        [Fact]
        public void DeleteStudent_CascadesEnrollments()
        {
            var student = new Student
            {
                LastName = "CascadeStudent",
                FirstMidName = "Test",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };
            _context.Students.Add(student);

            var dept = new Department
            {
                Name = "Cascade Dept",
                Budget = 50000,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var course = new Course
            {
                CourseID = 8001,
                Title = "Cascade Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();

            _context.Enrollments.Add(new Enrollment
            {
                StudentID = student.ID,
                CourseID = course.CourseID,
                Grade = Grade.B
            });
            _context.SaveChanges();

            _context.Students.Remove(student);
            _context.SaveChanges();

            Assert.Empty(_context.Enrollments.Where(e => e.StudentID == student.ID));
        }

        public void Dispose()
        {
            _context?.Dispose();
        }
    }
